examples/analysis_population.stat:
# Who is analysed. population= on an assignment says whether everyone randomised is
# analysed in the arm they were assigned to, or only participants left after exclusions.
use models.two_arm_binomial
use sampling
use tests.randomisation
use tests.fisher

# Everyone randomised, in the arm they were assigned to. A randomisation test's level
# rests on this, so the report lists it as declared rather than assumed.
let randomised = assignment(
    n_control=30,
    n_treatment=30,
    randomisation="complete",
    population="randomised",
)
let response = two_arm(assignment=randomised, outcome=binary_outcome(better="higher"))
let primary = randomisation_test(
    design=fixed(model=response),
    null=no_effect(model=response),
    alpha=1/20,
    draws=9999,
)

# Participants who followed the protocol: 4 control and 6 treatment participants were
# excluded after randomisation. A randomisation test here would be refused. Fisher's test
# keeps its bound, and its claim says the bound covers the per-protocol population only.
let adherent = assignment(n_control=26, n_treatment=24, population="per_protocol")
let completers = two_arm(assignment=adherent, outcome=binary_outcome(better="higher"))
let supportive = fisher(
    design=fixed(model=completers),
    null=equal_proportions(model=completers),
    alpha=1/20,
)

let everyone = verify(typeI(primary))
let per_protocol = verify(typeI(supportive))

examples/case_control.stat:
# A case-control study: cases with the outcome and controls without it, sampled in fixed
# numbers, then asked about past exposure. Only odds ratios are estimable; Fisher's test
# of no association is proved in Lean with the two groups in place of arms.
use models.observational
use sampling
use tests.association
use estimation.observational

let study = case_control(cases=120, controls=240, exposure="mobile phone use", outcome="glioma")
let analysis = fisher_exact(
    design=fixed(model=study),
    null=no_association(model=study),
    alpha=1/20,
)
let checked = verify(typeI(analysis))

let asked = observed_table(
    model=study,
    exposed_cases=64,
    exposed_noncases=112,
    unexposed_cases=56,
    unexposed_noncases=128,
)
let odds = verify(odds_ratio(table=asked, level=19/20))

examples/cluster_trial.stat:
# A cluster-randomised trial: twelve clinics, six per arm, every split equally likely.
# Two analyses of the same trial, one cited and one proved in Lean.
use models.two_arm_continuous
use sampling
use tests.cluster
use tests.randomisation
use planning

let clinics = cluster_assignment(
    clusters_control=6,
    clusters_treatment=6,
    n_control=120,
    n_treatment=120,
    randomisation="complete",
)
let practice = two_arm(assignment=clinics, outcome=continuous_outcome(better="higher"))

# A t-test on the twelve clinic means: the sample size is the clinics, not the people.
# Its guarantee is cited, exact if clinic means are normal with a common variance.
let summaries = cluster_t_test(
    design=fixed(model=practice),
    null=equal_means(model=practice),
    alpha=1/20,
)

# The randomisation test of the sharp null needs no assumption about the outcomes.
let permuted = randomisation_test(
    design=fixed(model=practice),
    null=no_effect(model=practice),
    alpha=1/20,
)

let cited = verify(typeI(summaries))
let proved = verify(typeI(permuted))

# Planning. A clinic's mean varies less than one patient's outcome, but patients in one
# clinic are alike: icc is the share of the variance between clinics.
let expected = mean_difference(value=5, sd=10, icc=1/20)
let target = power_target(at=expected, minimum=4/5, maximum_typeI=1/20)
let power = calculate(meets(analysis=summaries, target=target))
let clinics_needed = calculate(
    smallest_sample_size(
        candidates=cluster_counts(analysis=summaries, cluster_size=20, min_per_arm=4, max_per_arm=40),
        target=target,
    ),
)

# Clinics of unequal sizes, by simulation: their sizes vary with a coefficient of variation of 3/5.
let uneven = power_target(
    at=mean_difference(value=5, sd=10, icc=1/20, cluster_size_cv=3/5),
    minimum=4/5,
    maximum_typeI=1/20,
)
let simulated = simulate(meets(analysis=summaries, target=uneven), seed=2026)

examples/cohort.stat:
# A cohort that sampled exposed and unexposed groups in fixed numbers. It estimates risk,
# so the risk ratio and difference are available as well as the odds ratio.
use models.observational
use sampling
use tests.association
use estimation.observational

let followed = cohort(exposed=150, unexposed=300, exposure="statin use", outcome="dementia")
let test = fisher_exact(design=fixed(model=followed), null=no_association(model=followed), alpha=1/20)
let seen = observed_table(
    model=followed,
    exposed_cases=9,
    exposed_noncases=141,
    unexposed_cases=33,
    unexposed_noncases=267,
)
let result = verify(association_result(analysis=test, table=seen))
let ratio = verify(risk_ratio(table=seen, level=19/20))
let difference = calculate(risk_difference(table=seen, level=19/20))
let odds = calculate(odds_ratio(table=seen, level=19/20))

examples/confidence_interval.stat:
# Estimate a response rate with an exact 95% confidence interval.
use tests.binomial

let study = one_arm_binomial(n=35)

# Fourteen of 35 participants responded.
let interval = confidence_interval(model=study, count=14, level=19/20)
let calculation = calculate(interval)
let lower = calculation.calculation.lower
let upper = calculation.calculation.upper
let verification = verify(interval)

examples/confirmatory_trial.stat:
# A confirmatory trial: a survival primary endpoint with one interim look, then
# two secondary endpoints tested in order only if the primary succeeds.
use models.two_arm_survival
use models.two_arm_continuous
use models.two_arm_binomial
use sampling
use tests.survival
use tests.t
use tests.fisher
use designs.group_sequential
use multiplicity.fixed_sequence

# Primary: overall survival, analysed at 150 and at 300 participants per arm.
let interim_cohort = two_arm_survival(n_control=150, n_treatment=150)
let full_cohort = two_arm_survival(n_control=300, n_treatment=300)
let interim = log_rank(
    design=fixed(model=interim_cohort),
    null=equal_survival(model=interim_cohort),
    alpha=1/200,
)
let final = log_rank(
    design=fixed(model=full_cohort),
    null=equal_survival(model=full_cohort),
    alpha=9/200,
)
let survival = alpha_spending(looks=[interim, final], alpha=1/20)

# Secondary 1: change in a symptom score.
let scores = two_arm_continuous(n_control=300, n_treatment=300)
let symptoms = t_test(design=fixed(model=scores), null=equal_means(model=scores), alpha=1/20)

# Secondary 2: response, yes or no.
let responders = two_arm_binomial(n_control=300, n_treatment=300)
let response = fisher(
    design=fixed(model=responders),
    null=equal_proportions(model=responders),
    alpha=1/20,
)

# Test in this order at the full level; stop at the first endpoint that fails.
let hierarchy = fixed_sequence(analyses=[survival, symptoms, response], alpha=1/20)
let overall = verify(familywise(hierarchy))
let primary = verify(typeI(survival))
let exact_secondary = verify(typeI(response))

examples/cross_sectional.stat:
# Studies that fix only the total. A cross-sectional survey records exposure and outcome
# at once; a population cohort samples first and measures exposure at baseline. How many
# are exposed is random, so Fisher's test is proved by averaging over that number.
use models.observational
use sampling
use tests.association
use estimation.observational

let survey = cross_sectional(n=800, exposure="night shifts", outcome="insomnia")
let prevalence_test = fisher_exact(
    design=fixed(model=survey),
    null=no_association(model=survey),
    alpha=1/20,
)

let population = cohort(n=2500, exposure="air pollution", outcome="childhood asthma")
let risk_test = fisher_exact(
    design=fixed(model=population),
    null=no_association(model=population),
    alpha=1/40,
)

let survey_checked = verify(typeI(prevalence_test))
let cohort_checked = verify(typeI(risk_test))

let counted = observed_table(
    model=survey,
    exposed_cases=62,
    exposed_noncases=138,
    unexposed_cases=90,
    unexposed_noncases=510,
)
let prevalence = verify(prevalence_ratio(table=counted, level=19/20))

examples/declared_design.stat:
# Two designs a test's independence assumption can contradict, declared on the model.
use models.two_arm_continuous
use sampling
use tests.mixed_model
use tests.declared

# A symptom score measured at three visits on each of 150 participants per arm.
# A t-test here would be refused: it takes one value per participant.
let arms = assignment(n_control=150, n_treatment=150)
let visits = two_arm(assignment=arms, outcome=continuous_outcome(better="lower", measurements=3))
let symptoms = mmrm_test(
    design=fixed(model=visits),
    null=equal_means(model=visits),
    alpha=1/20,
)

# Twelve clinics per arm are randomised, with 240 participants per arm in all.
# A mixed model for clinics has no contract, so it is declared. cluster_t_test and
# randomisation_test have contracts; see cluster_trial.stat.
let clinics = cluster_assignment(
    clusters_control=12,
    clusters_treatment=12,
    n_control=240,
    n_treatment=240,
)
let practice = two_arm(assignment=clinics, outcome=continuous_outcome(better="higher"))
let adherence = declared_test(
    design=fixed(model=practice),
    null=equal_means(model=practice),
    alpha=1/20,
    method="Linear mixed model with a random intercept for clinic",
)

let repeated = verify(typeI(symptoms))
let clustered = verify(typeI(adherence))

examples/declared_test.stat:
# An analysis StatClaim has no contract for, declared by name.
# The plan's structure is still checked; the test itself is taken on trust.
use models.two_arm_continuous
use sampling
use tests.declared
use tests.t
use multiplicity.bonferroni

let study = two_arm_continuous(n_control=200, n_treatment=200)
let plan = fixed(model=study)

# A stratified rank test is not in StatClaim's registry, so name it and say
# where it is specified.
let pain = declared_test(
    design=plan,
    null=equal_means(model=study),
    alpha=1/40,
    method="Van Elteren stratified rank test, stratified by site",
    reference="Statistical analysis plan, section 9.2",
)
let function = t_test(design=plan, null=equal_means(model=study), alpha=1/40)

let endpoints = bonferroni(analyses=[pain, function], alpha=1/20)
let family = verify(familywise(endpoints))
let alone = verify(typeI(pain))

examples/difference_interval.stat:
# Estimate the difference between two success rates with a confidence interval.
use models.two_arm_binomial
use estimation

