examples/incidence_rates.stat:
# A cohort followed over person-time. Events in each group occur at a constant rate, so the
# exposed share of events, given their total, is binomial; equal rates make it the exposed
# share of person-time. Person-time may be fractional, such as person-years.
use models.observational
use sampling
use tests.association
use estimation.observational

let workers = person_time_cohort(exposure="solvent exposure", outcome="kidney cancer")
let test = rate_test(design=fixed(model=workers), null=no_association(model=workers), alpha=1/40)
let counted = observed_events(
    model=workers,
    exposed_events=19,
    exposed_time=8421.5,
    unexposed_events=34,
    unexposed_time=26310.25,
)
let design_claim = verify(typeI(test))
let result = verify(rate_result(analysis=test, events=counted))
let ratio = verify(rate_ratio(events=counted, level=39/40))

examples/interim_look.stat:
# One interim look at half the data, then the final analysis.
use models.two_arm_continuous
use sampling
use tests.t
use designs.group_sequential

# Each look is the same test at the cumulative sample size reached by then.
let halfway = two_arm_continuous(n_control=50, n_treatment=50)
let complete = two_arm_continuous(n_control=100, n_treatment=100)

let interim = t_test(design=fixed(model=halfway), null=equal_means(model=halfway), alpha=1/200)
let final = t_test(design=fixed(model=complete), null=equal_means(model=complete), alpha=9/200)

# Spend 0.005 at the interim look and 0.045 at the end: 0.05 overall.
let trial = alpha_spending(looks=[interim, final], alpha=1/20)
let overall = verify(typeI(trial))

# Power, the chance of stopping at each look and the expected size are simulated:
# estimates, beside the proved bound.
use planning
let target = power_target(at=mean_difference(value=5, sd=10), minimum=4/5, maximum_typeI=1/20)
let simulated = simulate(meets(analysis=trial, target=target), seed=2026)

examples/log_rank.stat:
# A time-to-event endpoint. The log-rank guarantee is cited and large-sample.
use models.two_arm_survival
use sampling
use tests.survival
use planning

let study = two_arm_survival(n_control=200, n_treatment=200)
let plan = fixed(model=study)
let null = equal_survival(model=study)

let analysis = log_rank(design=plan, null=null, alpha=1/20)
let checked = verify(typeI(analysis))
let scope = checked.claim.scope
let assumptions = checked.evidence.required_assumptions

# Planning from survival times: a control median of 12 months, a hazard ratio of 7/10,
# two years of accrual, a year of follow-up after it and 10% dropping out by a year.
# The arm sizes then give the expected events, so the sizes can be searched.
let expected = exponential_survival(
    hazard_ratio=7/10,
    control_median=12,
    accrual=24,
    follow_up=12,
    dropout=1/10,
    dropout_time=12,
)
let target = power_target(at=expected, minimum=4/5, maximum_typeI=1/20)
let power = calculate(meets(analysis=analysis, target=target))
let sizes = equal_arm_sizes(analysis=analysis, min_per_arm=50, max_per_arm=1000)
let sizing = calculate(smallest_sample_size(candidates=sizes, target=target))
let events = sizing.calculation.expected_events

# The same trial if the treatment takes three months to act: Schoenfeld's formula
# cannot say, so the trial is simulated, drawing every patient's time.
let late = exponential_survival(
    hazard_ratio=7/10,
    control_median=12,
    accrual=24,
    follow_up=12,
    dropout=1/10,
    dropout_time=12,
    effect_delay=3,
)
let delayed = power_target(at=late, minimum=4/5, maximum_typeI=1/20)
let delayed_power = simulate(meets(analysis=analysis, target=delayed), seed=2026)

examples/lower_is_better.stat:
# An outcome where lower is better, such as a symptom score. Declaring it lets
# StatClaim check that the one-sided null asks the right way round.
use models.two_arm_continuous
use sampling
use tests.mixed_model
use planning

let study = two_arm_continuous(n_control=400, n_treatment=400, better="lower")
let plan = fixed(model=study)

# Non-inferiority: the new treatment's score may be higher by at most 0.1.
# mean_difference_at_most here would be refused: it asks whether scores are higher.
let symptoms = mmrm_test_one_sided(
    design=plan,
    null=mean_difference_at_least(model=study, value=1/10),
    alpha=1/40,
)
let error = verify(typeI(symptoms))

# Power if the treatments are truly equal and the contrast's SD is 0.5.
let target = power_target(at=mean_difference(value=0, sd=1/2), minimum=4/5, maximum_typeI=1/40)
let power = calculate(meets(analysis=symptoms, target=target))

examples/matched_case_control.stat:
# A 1:1 matched case-control study. Each case of hip fracture was matched to one control of
# the same age, sex and practice. Only discordant pairs, where one of the two used the
# drug, carry information; an unmatched test would ignore the matching and is refused.
use models.observational
use sampling
use tests.association
use estimation.observational

let paired = matched_case_control(pairs=220, exposure="benzodiazepine use", outcome="hip fracture")
let analysis = mcnemar(design=fixed(model=paired), null=no_association(model=paired), alpha=1/20)
let seen = observed_pairs(
    model=paired,
    both_exposed=18,
    case_exposed_only=31,
    control_exposed_only=17,
    neither_exposed=154,
)
let result = verify(matched_result(analysis=analysis, pairs=seen))
let odds = verify(conditional_odds_ratio(pairs=seen, level=19/20))

examples/mixed_endpoints.stat:
# A binary and a continuous endpoint under one familywise error bound.
use models.two_arm_binomial
use models.two_arm_continuous
use sampling
use tests.fisher
use tests.t
use multiplicity.bonferroni

# Primary endpoint: response, yes or no. Its test is proved in Lean.
let responders = two_arm_binomial(n_control=120, n_treatment=120)
let response = fisher(
    design=fixed(model=responders),
    null=equal_proportions(model=responders),
    alpha=1/40,
)

# Secondary endpoint: change in a symptom score. Its test is cited.
let scores = two_arm_continuous(n_control=120, n_treatment=120)
let symptoms = t_test(
    design=fixed(model=scores),
    null=equal_means(model=scores),
    alpha=1/40,
)

let endpoints = bonferroni(analyses=[response, symptoms], alpha=1/20)
let family = verify(familywise(endpoints))
let primary = verify(typeI(response))

examples/non_inferiority.stat:
# A non-inferiority trial: the new treatment may be at most 10 points worse.
use models.two_arm_binomial
use sampling
use tests.difference
use planning

let study = two_arm_binomial(n_control=60, n_treatment=60)
let design = fixed(model=study)

# Null: the treatment's success rate is more than 10 points below the control's.
let null = proportion_difference_at_most(model=study, value=-1/10)
let analysis = difference_test(design=design, null=null, alpha=1/40)
let guarantee = verify(typeI(analysis))

# Planning: if both rates are truly 85%, how many participants give 50% power?
let target = power_target(
    at=binomial_rates(p_control=17/20, p_treatment=17/20),
    minimum=1/2,
    maximum_typeI=1/40,
)
let power = calculate(meets(analysis=analysis, target=target))
let candidates = equal_arm_sizes(analysis=analysis, min_per_arm=60, max_per_arm=120)
let sizing = calculate(sample_size(candidates=candidates, target=target))

# Analysis: 50 of 60 controls and 52 of 60 treated participants responded.
let data = observe(analysis=analysis, control_successes=50, treatment_successes=52)
let outcome = verify(result(data))

examples/observational_power.stat:
# Exact power of the proved observational tests: Fisher's test of no association in every
# design, McNemar's test for matched pairs, and the rate test given its events.
# Power is the exact probability that the test rejects at a planning point; verify has Lean
# recompute it. Power concerns association: it says nothing about an effect of the exposure.
use models.observational
use sampling
use tests.association
use planning

# A case-control study, planned at the share of controls exposed and the odds ratio.
let study = case_control(cases=50, controls=100, exposure="night shift work", outcome="breast cancer")
let analysis = fisher_exact(design=fixed(model=study), null=no_association(model=study), alpha=1/20)
let target = power_target(
    at=exposure_prevalence(controls=1/5, odds_ratio=3),
    minimum=4/5,
    maximum_typeI=1/20,
)
let proposed = calculate(meets(analysis=analysis, target=target))

# The smallest number of cases in the range, each with two controls.
let sizes = case_control_sizes(analysis=analysis, min_cases=40, max_cases=60, controls_per_case=2)
let smallest = verify(smallest_sample_size(candidates=sizes, target=target))

# A cohort that samples exposed and unexposed groups, planned at the risk in each.
let followed = cohort(exposed=100, unexposed=200, exposure="solvent exposure", outcome="kidney disease")
let test = fisher_exact(design=fixed(model=followed), null=no_association(model=followed), alpha=1/20)
let risk_target = power_target(at=risks(unexposed=1/20, exposed=3/20), minimum=4/5, maximum_typeI=1/20)
let risk_power = calculate(meets(analysis=test, target=risk_target))
let cohorts = cohort_sizes(analysis=test, min_exposed=50, max_exposed=200, unexposed_per_exposed=2)
let exposed_needed = calculate(smallest_sample_size(candidates=cohorts, target=risk_target))

# A 1:1 matched study, planned at the share of discordant pairs and the conditional odds ratio.
let paired = matched_case_control(pairs=60, exposure="benzodiazepine use", outcome="hip fracture")
let pairs_test = mcnemar(design=fixed(model=paired), null=no_association(model=paired), alpha=1/20)
let pairs_target = power_target(
    at=discordant_pairs(share=1/2, odds_ratio=3),
    minimum=4/5,
    maximum_typeI=1/20,
)
let pairs_power = calculate(meets(analysis=pairs_test, target=pairs_target))
let pair_counts = matched_sizes(analysis=pairs_test, min_pairs=55, max_pairs=80)
let fewest_pairs = verify(smallest_sample_size(candidates=pair_counts, target=pairs_target))

# A person-time cohort: power given 100 events, with a quarter of the person-time exposed.
let workers = person_time_cohort(exposure="shift work", outcome="type 2 diabetes")
let rates = rate_test(design=fixed(model=workers), null=no_association(model=workers), alpha=1/40)
let rates_target = power_target(
    at=incidence_rates(rate_ratio=2, exposed_time=8000, unexposed_time=24000, events=100),
    minimum=4/5,
    maximum_typeI=1/40,
)
let rates_power = verify(meets(analysis=rates, target=rates_target))

# A cross-sectional study fixes only its total, so the share exposed is part of the point.
let survey = cross_sectional(n=60, exposure="night shifts", outcome="insomnia")
let survey_test = fisher_exact(design=fixed(model=survey), null=no_association(model=survey), alpha=1/20)
let survey_target = power_target(
    at=outcome_prevalence(unexposed=1/10, exposed=1/2, exposed_share=3/10),
    minimum=4/5,
    maximum_typeI=1/20,
)
let survey_power = verify(meets(analysis=survey_test, target=survey_target))

examples/one_sample.stat:
# A single-arm study: is the response rate above 20%?
# One-sided exact binomial test, with a sample-size search.
use tests.binomial
use planning

let study = one_arm_binomial(n=25)
let analysis = binomial_test(model=study, null_rate=1/5, alpha=1/20)

# Planning input: we hope for a 40% response rate and want 80% power.
let target = power_target(at=response_rate(value=2/5), minimum=4/5, maximum_typeI=1/20)

# Twenty-five participants are not enough at this point.
let feasibility = meets(analysis=analysis, target=target)
let calculation = calculate(feasibility)

# Search for the smallest sample size in this range that meets the target.
let candidates = sample_sizes(analysis=analysis, min_n=10, max_n=60)
let sizing = smallest_sample_size(candidates=candidates, target=target)
let recommendation = calculate(sizing)
let verification = verify(sizing)
let recommended_n = recommendation.calculation.n
let critical_value = recommendation.calculation.critical_value

