examples/randomisation.stat:
# Randomisation tests. Their level follows from how the trial was randomised, so
# Lean proves it, for any test statistic fixed in advance and any outcome distribution.
use models.two_arm_continuous
use sampling
use tests.randomisation

# 40 participants, every split into two arms of 20 equally likely.
let arms = assignment(n_control=20, n_treatment=20, randomisation="complete")
let pain = two_arm(assignment=arms, outcome=continuous_outcome(better="lower"))

# The null is the sharp null: treatment changes no participant's pain score.
# It is not equal_means(...), which a randomisation test does not support.
# 40 participants have 137,846,528,820 splits, too many to count, so the p-value
# compares the observed split with 9,999 drawn at random. Lean proves that too.
let analysis = randomisation_test(
    design=fixed(model=pain),
    null=no_effect(model=pain),
    alpha=1/20,
    draws=9999,
)

# Twelve clinics randomised, six per arm: the test permutes clinics, not people.
let clinics = cluster_assignment(
    clusters_control=6,
    clusters_treatment=6,
    n_control=120,
    n_treatment=120,
    randomisation="complete",
)
let practice = two_arm(assignment=clinics, outcome=continuous_outcome(better="higher"))
let clustered = randomisation_test(
    design=fixed(model=practice),
    null=no_effect(model=practice),
    alpha=1/20,
)

let individual = verify(typeI(analysis))
let by_clinic = verify(typeI(clustered))
let status = by_clinic.status
let grade = by_clinic.evidence.grade

examples/randomisation_family.stat:
# A proved randomisation test as the primary analysis of a trial with two endpoints.
use models.two_arm_binomial
use models.two_arm_continuous
use sampling
use tests.randomisation
use tests.fisher
use multiplicity.fixed_sequence

# 120 participants randomised in permuted blocks of four.
let arms = assignment(n_control=60, n_treatment=60, randomisation="blocked", block_size=4)
let pain = two_arm(assignment=arms, outcome=continuous_outcome(better="lower"))
let relief = two_arm(assignment=arms, outcome=binary_outcome(better="higher"))

# Primary: a randomisation test of the sharp null, with 9,999 random draws.
let primary = randomisation_test(
    design=fixed(model=pain),
    null=no_effect(model=pain),
    alpha=1/20,
    draws=9999,
)

# Secondary, tested only if the primary rejects: Fisher's exact test.
let secondary = fisher(
    design=fixed(model=relief),
    null=equal_proportions(model=relief),
    alpha=1/20,
)

let order = fixed_sequence(analyses=[primary, secondary], alpha=1/20)
let trial = verify(familywise(order))
let first = verify(typeI(primary))

examples/recycling.stat:
# Co-primary endpoints with recycling, then secondary endpoints in a fixed order.
# This is the structure of many confirmatory trial plans.
use models.two_arm_continuous
use models.two_arm_binomial
use sampling
use tests.t
use tests.fisher
use multiplicity.graphical
use multiplicity.fixed_sequence

let per_protocol = two_arm_continuous(n_control=440, n_treatment=440)
let everyone = two_arm_continuous(n_control=500, n_treatment=500)
let responders = two_arm_binomial(n_control=500, n_treatment=500)

# Three primary questions about lung function, each declared at the overall level.
let trough_not_worse = welch_test_one_sided(
    design=fixed(model=per_protocol),
    null=mean_difference_at_most(model=per_protocol, value=-50),
    alpha=1/40,
)
let peak_not_worse = welch_test_one_sided(
    design=fixed(model=per_protocol),
    null=mean_difference_at_most(model=per_protocol, value=-50),
    alpha=1/40,
)
let peak_better = welch_test_one_sided(
    design=fixed(model=everyone),
    null=mean_difference_at_most(model=everyone, value=0),
    alpha=1/40,
)

# The level starts split between the two non-inferiority tests. After a
# rejection it is passed on: trough to peak, peak to superiority, and back.
let primary = graphical(
    analyses=[trough_not_worse, peak_not_worse, peak_better],
    weights=[1/2, 1/2, 0],
    transitions=[
        [0, 1, 0],
        [0, 0, 1],
        [1, 0, 0],
    ],
    alpha=1/40,
)

# Secondary endpoints are tested only if all three primary nulls are rejected.
let capacity = welch_test_one_sided(
    design=fixed(model=per_protocol),
    null=mean_difference_at_most(model=per_protocol, value=-50),
    alpha=1/40,
)
let onset = fisher_one_sided(
    design=fixed(model=responders),
    null=proportion_difference_at_most(model=responders, value=0),
    alpha=1/40,
)
let trial = fixed_sequence(analyses=[primary, capacity, onset], alpha=1/40)

let primary_error = verify(familywise(primary))
let overall_error = verify(familywise(trial))

examples/regression.stat:
# Regression tests of an exposure with covariates. Guarantees are cited, not proved: the
# compiler checks that each method fits the design, the measurement scales and the null.
use models.observational
use sampling
use tests.regression
use planning

let paired = matched_case_control(pairs=220, exposure="benzodiazepine use", outcome="hip fracture")
let conditional = conditional_logistic(
    design=fixed(model=paired),
    null=no_association(model=paired),
    alpha=1/20,
    adjusted_for=["dementia", "visual impairment"],
)

let workers = person_time_cohort(exposure="solvent exposure", outcome="kidney cancer")
let rates = poisson_rate_regression(
    design=fixed(model=workers),
    null=no_association(model=workers),
    alpha=1/20,
    adjusted_for=["age band", "calendar period"],
)

let followed = cohort(exposed=600, unexposed=1200, exposure="statin use", outcome="dementia")
let risk = modified_poisson(
    design=fixed(model=followed),
    null=no_association(model=followed),
    alpha=1/20,
    adjusted_for=["age", "diabetes"],
)

let conditional_claim = verify(typeI(conditional))
let rates_claim = verify(typeI(rates))
let risk_claim = verify(typeI(risk))

# Power for a measured exposure and outcome: the slope of systolic pressure on BMI.
let clinic = cross_sectional(
    n=250,
    exposure="BMI",
    outcome="systolic pressure",
    exposure_scale="continuous",
    outcome_scale="continuous",
)
let fitted = linear_association(
    design=fixed(model=clinic),
    null=no_association(model=clinic),
    alpha=1/20,
    adjusted_for=["age", "sex"],
)
let target = power_target(
    at=slope(value=1/2, exposure_sd=4, residual_sd=15, exposure_r2=1/10),
    minimum=9/10,
    maximum_typeI=1/20,
)
let power = calculate(meets(analysis=fitted, target=target))
let needed = calculate(
    smallest_sample_size(candidates=total_sizes(analysis=fitted, min_n=10, max_n=5000), target=target),
)

# The same slope unadjusted, if the pressure's error were skewed: its power is simulated,
# and its Type I error judged against Bradley's 3/40.
let unadjusted = linear_association(design=fixed(model=clinic), null=no_association(model=clinic), alpha=1/20)
let skewed = power_target(
    at=slope(value=1/2, exposure_sd=4, residual_sd=15, skewness=2),
    minimum=9/10,
    maximum_typeI=3/40,
)
let skewed_power = simulate(meets(analysis=unadjusted, target=skewed), seed=2026)

